if (path === '/order') {
  const o = ORDERS[q.id];
  if (!o) return html('<h1>Commande introuvable</h1>');
  const isAdmin = /session=admin-7c9e/.test(headers.cookie || '');
  let me = '';
  try { me = decodeURIComponent((Object.fromEntries((headers.cookie || '').split(';').map((c) => { const i = c.indexOf('='); return i < 0 ? [] : [c.slice(0, i).trim(), c.slice(i + 1).trim()]; })).customer || '')); } catch { me = ''; }
  if (!isAdmin && me !== o.email) return [403, { 'content-type': 'text/html; charset=utf-8' }, '<h1>Accès refusé</h1>'];
  return html(page('order.html').replace('<!--ORDER-->', `<p><b>Commande ${esc(q.id)}</b></p><p>${esc(o.customer)} · ${esc(o.email)}<br>${esc(o.address)}<br>Total ${o.total} € · carte ${o.card}</p>`));
}

